    attribute pressedStartStep : Integer := 0;
    attribute accumulatedPressedMs : Integer := 0;
    attribute reportPending : Boolean := false;
    attribute reportedDurationSeconds : Real := 0.0;
    perform action tick {
      first start;
      then if ((io_0) and ((not previousPressed))) {
        first start;
        then assign pressedStartStep := 0;
        then assign accumulatedPressedMs := 0;
        then assign reportPending := false;
      }
      then if io_0 {
        first start;
        then assign accumulatedPressedMs := accumulatedPressedMs + 5;
      }
      then if (((not io_0)) and (previousPressed)) {
        first start;
        then assign reportedDurationSeconds := accumulatedPressedMs / 1000.0;
        then assign reportPending := true;
        then assign accumulatedPressedMs := 0;
      }
      then if reportPending {
        first start;
        then assign reportPending := false;
      }
      then assign previousPressed := io_0;
    }
